<?php
declare(strict_types=1);
putenv('COREFLUX_DISABLE_DATABASE=1');
require_once __DIR__.'/../core/custom_fields.php';
$passed=0;$check=static function(bool$ok,string$label)use(&$passed):void{if(!$ok)throw new RuntimeException($label);$passed++;echo "PASS $label\n";};
$fails=static function(callable$f):bool{try{$f();return false;}catch(Throwable$e){return true;}};
$registry=customFieldEntityRegistry();
$check(array_keys($registry)===['people','companies','placements'],'real manifests declare the three staffing custom entities');
$check($registry['people']['definition_table']==='people_custom_field_defs'&&$registry['companies']['owner_module']==='companies','existing people storage and separate company ownership retained');
$check(customFieldEntity('person')===null&&customFieldEntity('arbitrary_table')===null,'payload singular names and unknown tables cannot select storage');
$typed=static fn(string$type,mixed$value,array$extra=[])=>customFieldTypedValue(['field_type'=>$type,'required'=>0]+$extra,$value);
foreach([false,0,'0','false']as$v)$check($typed('boolean',$v)===false,'explicit false preserved '.json_encode($v));
foreach([true,1,'1','true']as$v)$check($typed('boolean',$v)===true,'explicit true preserved '.json_encode($v));
foreach(['yes',2,'',[],null]as$v)if($v!==null)$check($fails(fn()=>$typed('boolean',$v)),'ambiguous boolean rejected '.json_encode($v));
$check($typed('number','99999999999999.999999')==='99999999999999.999999','maximum native decimal is preserved without float conversion');
$check($typed('number','-0.000000')==='0'&&$typed('number','12.340000')==='12.34','equivalent decimals normalize without rounding');
foreach(['$12','12 hours','1e3','0.0000001','100000000000000',true]as$v)$check($fails(fn()=>$typed('number',$v)),'invalid numeric source rejected '.json_encode($v));
$check($typed('date','2028-02-29')==='2028-02-29','calendar leap day accepted');
foreach(['2026-02-29','10/01/2026','next Friday','2026-1-01']as$v)$check($fails(fn()=>$typed('date',$v)),'inferred or invalid date rejected '.$v);
$check($typed('text','0')==='0'&&$typed('text','')==='','literal text zero and empty text remain distinct');
$check($typed('text',null)===null&&$fails(fn()=>customFieldTypedValue(['field_type'=>'text','required'=>1],null)),'explicit clear respects required fields');
$options=['options_json'=>'["A","B"]'];
$check($typed('select','A',$options)==='A'&&$typed('multiselect',['B','A','B'],$options)===['A','B'],'choices are validated and multiselect replay is order independent');
$check($fails(fn()=>$typed('select','C',$options))&&$fails(fn()=>$typed('multiselect','A',$options)),'unknown and malformed choices rejected');
$row=['field_type'=>'number','value_text'=>'12.340000','value_number'=>null,'value_date'=>null,'value_boolean'=>null,'legacy_value_storage'=>true];
$check(customFieldNormalizeValueRow($row)['value']==='12.34','generic numeric read does not silently become null');
$row['field_type']='boolean';$row['value_text']='0';$check(customFieldNormalizeValueRow($row)['value']===false,'generic false read does not silently become null');
$row['field_type']='date';$row['value_text']='2026-10-01';$check(customFieldNormalizeValueRow($row)['value']==='2026-10-01','generic date read retains its value');
$row['legacy_value_storage']=false;$row['field_type']='number';$row['value_number']='8.500000';$row['value_text']=null;
$check(customFieldNormalizeValueRow($row)['value']==='8.5','people decimal read preserves exact string precision');
echo "Staffing custom fields: $passed passed\n";
